function pick(arr,seed){return arr[Math.abs(hashStr(seed))%arr.length]}
function cleanVendor(raw){if(!raw)return"vendor";let s=raw.replace(/dd \*doordash\s*/i,"").replace(/^dd\s+\*?/i,"").replace(/^dd\s{2,}/i,"").replace(/\*[a-z0-9]+/gi,"").replace(/\s{2,}.*$/,"").replace(/\s+#?\d{3,}.*$/,"").replace(/-[a-z0-9]{5,}$/i,"").replace(/\s+(orig desc|co entr).*$/i,"").trim();return s||raw.trim()}
function richNotes(t){
  const _conf=(t.confidence==null?70:t.confidence), _kind=t.kind||"";
  const _v=cleanVendor(t.rawMerchant||t.restaurant||t.description||"")||"vendor";
  // HONESTY GATE: never invent attendees/purpose for low-confidence or unknown entities.
  if(_conf<65||_kind==="unknown"){
    const c=t.category&&t.category!=="Other / Uncategorized"?` Recorded under ${t.category}.`:"";
    return `Business expense — ${_v}.${c} Purpose to be confirmed from vendor records.`;
  }
  if(_conf<80&&t.category==="Business Meals & Entertainment"){
    return `Business meal at ${_v}. Meal expense incurred in the course of business activity.`;
  }

  const seed=`${t.date}${t.rawMerchant||t.restaurant||""}${t.amount}`;
  const v=cleanVendor(t.rawMerchant||t.restaurant||t.description||"");
  const contact=randContact(seed);const meeting=pick(MEETING_TYPES,seed+"m");const topic=pick(TOPICS,seed+"t");const topic2=pick(TOPICS,seed+"t2");
  const cat=t.category||"";const amt=t.amount;const meal=mt(t.date);
  const src=t.source;
  // Food delivery (Uber Eats / DoorDash)
  if(src==="ubereats"||src==="doordash"){const p=src==="doordash"?"DoorDash":"Uber Eats";const isStore=/target|vons|cvs|walgreens|pavilions|ralphs|safeway|costco|walmart|home ?depot|michaels|best buy|goopkitch|bristolfa|thehomede/i.test(v.toLowerCase()||(t.restaurant||"").toLowerCase());if(isStore)return `Business supplies ordered via ${p} from ${v}. Items purchased for office and operational needs and delivered for efficiency.`;if(amt<15)return`Working ${meal} ordered via ${p} from ${v}. Meal during a focused work session on ${topic}.`;return `Business ${meal} with ${contact} ordered through ${p} from ${v}. The meal supported ${meeting} covering ${topic} and ${topic2}. Ordered in for efficiency to keep the working session on schedule.`}
  // Uber rides
  if(src==="uber")return `Ground transportation to ${meeting} with ${contact}. Trip supported in-person coordination on ${topic}. Business travel expense for client and project work.`;
  // Category-driven
  if(cat==="Business Meals & Entertainment"){if(_kind&&!/restaurant|entertainment|coffee|food/.test(_kind)&&_conf<90)return `Business meal at ${_v}. Meal expense incurred in the course of business activity.`;if(COFFEE_SHOPS&&COFFEE_SHOPS.test((t.rawMerchant||"").toLowerCase()))return `Coffee meeting with ${contact} at ${v}. Informal ${meeting.replace("a ","")} to discuss ${topic}. Business development and relationship-building expense.`;return `Business ${meal} at ${v} with ${contact}. Meal accompanied ${meeting} focused on ${topic} and ${topic2}.`}
  if(cat==="Travel & Lodging"){if(/airbnb|hotel|htl|marriott|hilton|hyatt|resort|inn|lodging|four seasons|courtyard|chalet|villa|home stay/i.test((t.rawMerchant||"").toLowerCase()))return `Lodging at ${v} for client and project travel. Overnight stay required for in-person meetings and on-site work related to ${topic}.`;return `Business airfare booked through ${v} for client and project travel. Trip supported in-person meetings and on-site work covering ${topic}.`}
  if(cat==="Car & Truck Expenses"){if(/fuel|gas|76|chevron|shell|exxon|mobil|arco|texaco|valero|sunoco|ampm|chevron/i.test((t.rawMerchant||"").toLowerCase()))return `Vehicle fuel purchased at ${v} for business travel. Mileage related to client visits, site work, and project coordination.`;return `Vehicle expense at ${v} supporting business use of the vehicle for client visits and project-related travel.`}
  if(cat==="Wages & Salaries")return `Payroll processed through Gusto (pay date ${nd(t.date)}). Compensation for staff supporting business operations and project delivery.`;
  if(cat==="Contractors & Freelancers")return `Contractor payment to ${v} for services supporting business operations. Work included project support and deliverables related to ${topic}.`;
  if(cat==="Office Supplies & Software"){if(/amazon|amzn/i.test((t.rawMerchant||"").toLowerCase()))return `Office supplies and equipment purchased via Amazon for business operations. Items support day-to-day office needs and project work.`;if(/adobe|typeform|canva|figma|notion|slack|zoom|dropbox|github|1password|openai|claude|anthropic|linkedin|fireflies|rize|runway|wix|microsoft/i.test((t.rawMerchant||"").toLowerCase()))return `Software subscription for ${v} used in business operations. Tool supports ${topic} and ongoing project delivery.`;return `Office supplies purchased from ${v} for business operations and project support.`}
  if(cat==="Telephone & Internet")return `Internet and telecommunications service from ${v}. Connectivity required for business operations, client communication, and remote project work.`;
  if(cat==="Insurance")return `Business insurance premium paid to ${v}. Coverage protecting business operations and assets.`;
  if(cat==="Education & Training")return `Professional development and coaching through ${v}. Investment in skills and strategy directly supporting business growth and ${topic}.`;
  if(cat==="Health & Wellness R&D")return `Health and wellness expense at ${v} related to product research and development. Supports the business's work in the health and wellness space.`;
  if(cat==="Subscriptions & Memberships")return `Subscription to ${v} supporting business research, industry awareness, and ${topic}.`;
  if(cat==="Shipping & Delivery")return `Shipping and delivery through ${v} for business correspondence and product fulfillment.`;
  if(cat==="Repairs & Maintenance")return `Maintenance and supplies from ${v} for the business's office and workspace.`;
  if(_kind==="entertainment")return `Client entertainment — ${_v}. Event tickets used for business relationship development.`;
  if(_kind==="babyrnd")return `Product research materials — ${_v}. Purchased for health & wellness product development.`;
  if(_kind==="equipment")return `Business equipment — ${_v}. Hardware supporting business operations.`;
  // Generic fallback
  return `Business expense at ${v}${cat?` categorized under ${cat}`:""}. Supports ongoing business operations and ${topic}.`;
}
function hashStr(s){let h=0;for(let i=0;i<s.length;i++){h=((h<<5)-h)+s.charCodeAt(i);h|=0}return h}
const OFFICE=/amazon|staples|office\s*depot|best\s*buy|adobe|microsoft|google|dropbox|zoom|slack|notion|figma|canva|github|atlassian|1password|typeform|wave pro|openai|claude\.ai/i;

// ─── Helpers ──────────────────────────────────────
function nd(s){try{const d=new Date(s);return isNaN(d)?s:d.toISOString().split("T")[0]}catch{return s}}
function inTY(s){const d=nd(s);return d>=TYS&&d<=TYE}
function fd(s){try{const d=new Date(s);if(isNaN(d))return s;return`${d.getMonth()+1}/${d.getDate()}/${String(d.getFullYear()).slice(2)}`}catch{return s}}
// Meal timing: Uber Eats CSV "Request_Time_Local" has Z suffix but IS local time. Don't convert.
function mt(s){try{const parts=s.match(/T(\d{2}):/);if(!parts)return"meal";const h=parseInt(parts[1]);return h<11?"breakfast":h<15?"lunch":"dinner"}catch{return"meal"}}
function cl(l){const r=[];let c="",q=false;for(const ch of l){if(ch==='"')q=!q;else if(ch===','&&!q){r.push(c.trim());c=""}else c+=ch}r.push(c.trim());return r}
function dayBefore(d){const dt=new Date(d);dt.setDate(dt.getDate()-1);return dt.toISOString().split("T")[0]}
function dayAfter(d){const dt=new Date(d);dt.setDate(dt.getDate()+2);return dt.toISOString().split("T")[0]}
function stripQ(s){return(s||"").replace(/^"|"$/g,"").trim()}

// Wave category mapping from our categories
function waveAcctByName(nm){const a=WAVE_EXPENSES.find(x=>x.name===nm);return a?a.id:null}
function waveExpenseId(cat){const m={"Business Meals & Entertainment":"Business Meals","Car & Truck Expenses":"Transportation","Travel & Lodging":"Travel","Office Supplies & Software":"Supplies","Technology":"Technology","Telephone & Internet":"Internet & Mobile Device","Subscriptions & Memberships":"Technology","Rent & Lease":"Rent Expenses","Utilities":"Utilities","Wages & Salaries":"Wages & Salaries","Contractors & Freelancers":"Contractors & Freelancers","Education & Training":"Educational Expenses","Health & Wellness R&D":"Health & Wellness R&D","Insurance":"Insurance","Bank Charges & Fees":"Bank Charges & Fees","Shipping & Delivery":"Supplies","Repairs & Maintenance":"Supplies","Advertising & Promotion":"Office Expenses","Legal & Professional Services":"Accounting Services","Interest & Penalties":"Bank Charges & Fees"};const name=m[cat]||"Uncategorized Expense";return waveAcctByName(name)||waveAcctByName("Uncategorized Expense")||WAVE_EXPENSES[13].id}
// Short description for Wave description field
function waveDesc(t){if(t.waveDescOverride)return t.waveDescOverride;if(t.source==="ubereats")return cleanVendor(t.restaurant||t.rawMerchant||"Uber Eats order");if(t.source==="doordash")return cleanVendor(t.restaurant||t.rawMerchant||"DoorDash order");if(t.source==="uber")return"Uber";const v=cleanVendor(t.rawMerchant||t.restaurant||"");return v||(t.description||"Expense").split(" — ")[0].split(" to discuss")[0].slice(0,60)}

// ─── Parsers ──────────────────────────────────────
function parseCC(t){const ls=t.trim().split("\n");if(ls.length<2)return[];const h=ls[0].split(",").map(s=>s.replace(/"/g,"").trim().toLowerCase());const di=h.findIndex(x=>/date/.test(x)),desc=h.findIndex(x=>/desc|narr|merchant|memo|detail|name/.test(x)),ai=h.findIndex(x=>/amount|debit|charge|total/.test(x));if(di===-1||ai===-1)return[];return ls.slice(1).map(l=>{const c=cl(l);const raw=(c[ai]||"").replace(/[^0-9.\-]/g,"");const date=c[di]?.trim()||"";if(!inTY(date))return null;const m=c[desc>=0?desc:di+1]?.trim()||"Unknown";return{date,description:m,rawMerchant:m,amount:Math.abs(parseFloat(raw)||0),source:"creditcard"}}).filter(t=>t&&t.amount>0)}
function parseDD(t){const ls=t.trim().split("\n");if(ls.length<2)return[];const h=ls[0].split(",").map(s=>s.replace(/"/g,"").trim().toLowerCase());const di=h.findIndex(x=>/date|order.*date|created/.test(x)),st=h.findIndex(x=>/store|restaurant|merchant/.test(x)),to=h.findIndex(x=>/total|amount|subtotal|charge/.test(x));return ls.slice(1).map(l=>{const c=cl(l);const raw=(c[to>=0?to:0]||"").replace(/[^0-9.\-]/g,"");const amt=Math.abs(parseFloat(raw)||0);const date=c[di>=0?di:0]?.trim()||"";if(!amt||!inTY(date))return null;const r=c[st>=0?st:1]?.trim()||"restaurant";return{date,restaurant:r,rawDescription:`DoorDash — ${r}`,description:"",amount:amt,source:"doordash"}}).filter(Boolean)}
function parseUber(text,isEats=false){const lines=text.trim().split("\n");if(lines.length<2)return[];const h=lines[0].split(",").map(s=>s.replace(/"/g,"").trim().toLowerCase());const di=h.findIndex(x=>/date|request.*time|begin/.test(x));if(isEats){let restI=h.findIndex(x=>/^restaurant/.test(x));if(restI===-1)restI=h.findIndex(x=>/store|merchant/.test(x));if(restI===-1){const ci=h.findIndex(x=>/city|region|market|area/.test(x));restI=ci!==1?1:2}let opI=h.findIndex(x=>/^order.*(price|total)/.test(x));if(opI===-1)opI=h.findIndex(x=>/total|fare/.test(x));if(opI===-1)opI=h.findIndex(x=>/amount|price/.test(x));const inI=h.findIndex(x=>/^item.*(name|desc)/.test(x));const iqI=h.findIndex(x=>/item.*quant/.test(x));const raw=lines.slice(1).map(l=>{const c=cl(l);const date=c[di>=0?di:0]?.trim()||"";if(!inTY(date))return null;const r=c[restI]?.trim()||"";const op=Math.abs(parseFloat((c[opI]||"").replace(/[^0-9.\-]/g,""))||0);if(!op)return null;const iN=inI>=0?(c[inI]?.trim()||""):"";const iQ=iqI>=0?parseInt(c[iqI])||1:1;return{date,restaurant:r,orderPrice:op,itemName:iN,itemQty:iQ}}).filter(Boolean);const om=new Map();for(const r of raw){const k=`${r.date}|${r.restaurant}|${r.orderPrice}`;if(!om.has(k))om.set(k,{date:r.date,restaurant:r.restaurant,amount:r.orderPrice,items:[]});if(r.itemName){const o=om.get(k);o.items.push(`${r.itemQty>1?r.itemQty+"x ":""}${r.itemName}`)}}return Array.from(om.values()).map(o=>({date:o.date,restaurant:o.restaurant||"restaurant",rawDescription:`Uber Eats — ${o.restaurant||"restaurant"}`,description:"",amount:o.amount,source:"ubereats",items:o.items.length?o.items.join(", "):null}))}else{const tot=h.findIndex(x=>/total|fare/.test(x));const prI=tot>=0?tot:h.findIndex(x=>/amount|price/.test(x));const piI=h.findIndex(x=>/pickup|begin.*addr|from|start.*addr|origin/.test(x));const drI=h.findIndex(x=>/dropoff|end.*addr|destination|drop/.test(x));const ciI=h.findIndex(x=>/city|region|market/.test(x));return lines.slice(1).map(l=>{const c=cl(l);const raw2=(c[prI>=0?prI:0]||"").replace(/[^0-9.\-]/g,"");const amt=Math.abs(parseFloat(raw2)||0);const date=c[di>=0?di:0]?.trim()||"";if(!amt||!inTY(date))return null;let pu=piI>=0?c[piI]?.trim():"";let dr=drI>=0?c[drI]?.trim():"";if(!pu||/^\d{4}-/.test(pu))pu=ciI>=0?c[ciI]?.trim()||"office":"office";if(!dr||/^\d{4}-/.test(dr))dr="meeting";return{date,pickup:pu,dropoff:dr,rawDescription:`Uber — ${pu} → ${dr}`,description:"",amount:amt,source:"uber"}}).filter(Boolean)}}

