function genDesc(t){const seed=`${t.date}${t.restaurant||t.rawMerchant||""}${t.amount}`;if(t.source==="doordash"||t.source==="ubereats"){const r=t.restaurant||"restaurant";const p=t.source==="doordash"?"DoorDash":"Uber Eats";if(t.amount<15){if(COFFEE.test(r))return`Coffee at ${r} (${p})`;return`Snack at ${r} (${p})`}return`Business ${mt(t.date)} at ${r} (${p}) with ${randContact(seed)} ${randPurpose(seed+"p")}`}if(t.source==="uber")return`Uber ride: ${t.pickup||"office"} → ${t.dropoff||"meeting"}, for meeting with ${randContact(seed)} ${randPurpose(seed+"p")}`;const m=t.rawMerchant||t.description||"";if(OFFICE.test(m)&&t.amount<500)return`Office supplies — ${m}`;if(COFFEE.test(m)&&t.amount<15)return`Coffee — ${m}`;return m}
