const KB_MAP=(()=>{const m=new Map();for(const[cat,kind,list]of KB)for(const v of list)m.set(v,{cat,kind});return m})();
const KB_KEYS=[...KB_MAP.keys()].sort((a,b)=>b.length-a.length);

// ─── L0: NORMALIZER ───────────────────────────────
const PROC_PREFIX=/^(sq|tst|sp|pp|paypal|pypl|wf|fd|cl|dd|web|in|pos|apl|fh|dj|d j|sm|abc|rch)\s*\*\s*/i;
function normVendor(raw){if(!raw)return"";let s=String(raw).trim();s=s.replace(PROC_PREFIX,"");s=s.replace(/^dd\s+\*?\s*doordash\s*/i,"");s=s.replace(/^dd\s{1,}/i,"");s=s.replace(/\*[a-z0-9]{4,}$/i,"");s=s.replace(/\s+#?\d{3,}.*$/,"");s=s.replace(/\s{2,}.*$/,"");s=s.replace(/\s+(orig desc|co entr|trace#).*$/i,"");s=s.replace(/[-\s]+(ca|ny|tx|fl|wa|il|gb|us|usa)$/i,"");return s.trim().toLowerCase()}

// ─── L4: MORPHOLOGY SIGNALS ───────────────────────
const FOOD_TOKEN=/\b(cafe|caf\u00e9|coffee|grill|grille|kitchen|bar|tavern|bistro|pizzeria|pizza|taqueria|taco|sushi|ramen|deli|diner|steakhouse|brewery|brewing|eatery|restaurant|resto|bbq|thai|noodle|burger|sandwich|bakery|patisserie|creamery|juice|smoothie|boba|donut|bagel|wings|seafood|oyster|chophouse|trattoria|osteria|cantina|pub|lounge|kabab|curry|pho|dumpling|wok|enoteca|ciderworks|winery|gastro|kababs|shawarma|falafel|dosa|biryani|shack|crab|lobster|steak|chicken|sports ?bar|ale ?house|roadhouse|creperie|churrasc|izakaya|teriyaki|hibachi|tapas|brasserie|rotisserie|smokehouse|barbeque|barbecue|panini|gelato|ice ?cream|frozen ?yogurt|patio|kabob|grillhouse|noodles|bowls?|eats)\b/i;
const CORP_TOKEN=/\b(inc|corp|corporation|llc|ltd|technologies|systems|solutions|labs?|industries|holdings|group|enterprises|company|co)\b|\.(com|io|ai|net|org)\b/i;
const RETAIL_TOKEN=/\b(store|shop|market|supply|outfitters|goods|mercantile|boutique|depot|warehouse|outlet)\b/i;
const MED_TOKEN=/\b(medical|clinic|health|dental|dentist|pediatric|urgent care|hospital|physician|md\b|dds\b|therapy|diagnostic|pharmacy|surgery|orthodon)\b/i;
const EDU_TOKEN=/\b(academy|institute|university|college|school|training|course|learning|certification|seminar|workshop)\b/i;

// ─── RESOLVER: evidence-ranked ────────────────────
// Returns {cat, kind, conf, action, tier}
function resolveVendor(t){
  const raw=t.rawMerchant||t.restaurant||t.description||"";
  const nv=normVendor(raw);
  const cop=t.copilotCategory||"";
  if(!nv)return null;

  // L1b: SOURCE-DERIVED — delivery platforms are definitive evidence of food (unless a store)
  const rawLow=String(raw).toLowerCase();
  const isDelivery=/doordash|uber ?eats|grubhub|postmates|seamless|caviar/.test(rawLow)||t.source==="doordash"||t.source==="ubereats";
  const STORE_RX=/target|vons|cvs|walgreens|pavilions|ralphs|safeway|costco|walmart|home ?depot|michaels|best buy|officedep|office depot|staples|petco|petsmart|totalwine|total wine|bevmo|sprouts|whole ?foods|7-?eleven|rite aid|dollar tree/;
  if(isDelivery){
    if(STORE_RX.test(rawLow))return{cat:"Office Supplies & Software",kind:"retail",conf:88,action:"approve",tier:"src"};
    return{cat:"Business Meals & Entertainment",kind:"restaurant",conf:92,action:"approve",tier:"src"};
  }
  // L2: knowledge base (longest-key-first so "amazon mktpl" beats "amazon")
  for(const k of KB_KEYS){if(nv.includes(k)){const e=KB_MAP.get(k);
    if(e.cat==="DISCARD")return{cat:"Other / Uncategorized",kind:e.kind,conf:92,action:"discard",tier:"KB"};
    return{cat:e.cat,kind:e.kind,conf:93,action:"approve",tier:"KB"}}}

  // L4: morphology (only reached when KB + patterns miss)
  const isFood=FOOD_TOKEN.test(nv), isCorp=CORP_TOKEN.test(nv), isRetail=RETAIL_TOKEN.test(nv);
  if(MED_TOKEN.test(nv))return{cat:"Other / Uncategorized",kind:"medical",conf:82,action:"discard",tier:"morph"};
  if(EDU_TOKEN.test(nv))return{cat:"Education & Training",kind:"education",conf:76,action:"approve",tier:"morph"};
  // MEALS GATE: food classification requires positive food evidence, never corporate-looking names
  if(isFood&&!isCorp)return{cat:"Business Meals & Entertainment",kind:"restaurant",conf:80,action:"approve",tier:"morph"};
  if(isRetail&&!isFood)return{cat:"Office Supplies & Software",kind:"retail",conf:74,action:"approve",tier:"morph"};
  if(isCorp&&!isFood)return{cat:"Office Supplies & Software",kind:"vendor",conf:68,action:"triage",tier:"morph"};

  // L6: Copilot prior — weak, and CANNOT produce Business Meals on its own
  const COP_SAFE={"Travel & Vacation":["Travel & Lodging","travel",58],"Shops":["Office Supplies & Software","retail",62],"Clothing":["Office Supplies & Software","apparel",62],"Groceries":["Office Supplies & Software","retail",58],"Car":["Car & Truck Expenses","vehicle",64],"Transportation":["Car & Truck Expenses","transit",58],"Subscriptions":["Subscriptions & Memberships","subscription",60],"Gym":["Health & Wellness R&D","wellness",58],"Home":["Office Supplies & Software","retail",56],"Insurance":["Insurance","insurance",70],"Rent":["Rent & Lease","rent",64],"Utilities":["Utilities","utility",66]};
  if(cop==="Healthcare"||cop==="Donations")return{cat:"Other / Uncategorized",kind:"personal",conf:75,action:"discard",tier:"cop"};
  if(COP_SAFE[cop]){const[c,k,cf]=COP_SAFE[cop];return{cat:c,kind:k,conf:cf,action:"triage",tier:"cop"}}
  // Restaurants prior WITHOUT food evidence => NOT a meal. Unknown, needs review.
  if(cop==="Restaurants")return{cat:"Other / Uncategorized",kind:"unknown",conf:40,action:"triage",tier:"cop-weak"};
  return{cat:"Other / Uncategorized",kind:"unknown",conf:35,action:"triage",tier:"none"};
}

function vendorRule(t){
  const n=(t.rawMerchant||t.restaurant||t.description||"").toLowerCase();
  const cat=t.copilotCategory||"";
  const amt=t.amount;
  // PAYROLL
  if(/gusto/i.test(n))return{cat:"Wages & Salaries",conf:96,action:"approve",desc:`Payroll — Gusto (${nd(t.date)})`};
  // CONTRACTORS
  if(CONTRACTORS.test(n)){const who=/ws jones|jones consulting/i.test(n)?"WS Jones Consulting":/taskrabbit/i.test(n)?"TaskRabbit":/venmo/i.test(n)?"Venmo":/zelle/i.test(n)?"Zelle":"contractor";return{cat:"Contractors & Freelancers",conf:88,action:"approve",desc:`Contractor payment — ${who}`}}
  // BANK CHARGES / INTEREST / FEES → business cards
  if(/late fee|interest charge|purchase interest|interest on pay|finance charge|annual fee|renewal membership fee|foreign transaction fee|overdraft/i.test(n))return{cat:"Bank Charges & Fees",conf:94,action:"approve",desc:`Bank charge — ${cleanVendor(t.rawMerchant||"fee")}`};
  // MEDICAL → discard (personal)
  if(/med sinai|sinai medical|labcorp|village birth|one medical|hims & hers|quest diagnostic|kaiser|cedars|pediatric|dental|dentist|optometr|urgent care|pharmacy rx|medical group|health partners|physical therapy/i.test(n))return{cat:"Other / Uncategorized",conf:90,action:"discard",desc:""};
  // LITTLE SPROUT → baby equipment R&D
  if(/little sprout/i.test(n))return{cat:"Health & Wellness R&D",conf:88,action:"approve",desc:`Product R&D materials — ${cleanVendor(t.rawMerchant||"Little Sprout")}`};
  // ══ FEES & LICENSES ══
  if(/wire fee|incoming wire fee|membership fee|renewal membership/i.test(n))return{cat:"Bank Charges & Fees",conf:92,action:"approve",desc:`Bank & membership fee — ${cleanVendor(t.rawMerchant||"fee")}.`};
  if(/\bdmv\b|ca dmv|dept of motor|vehicle registration|business license|city of .*license|secretary of state|franchise tax/i.test(n))return{cat:"Taxes & Licenses",conf:90,action:"approve",desc:`Registration & licensing — ${cleanVendor(t.rawMerchant||"license")}. Required for business operations.`};
  // ══ COACHING / NUTRITION PROGRAMS → Education ══
  if(/\blevels\b|\bverb\b|dance street|elegance preserved/i.test(n))return{cat:"Education & Training",conf:85,action:"approve",desc:`Professional coaching & development — ${cleanVendor(t.rawMerchant||"coaching")}. Supports business skills and strategy.`};
  // ══ MEAL SUBSCRIPTIONS → discard (personal) ══
  if(/cookunity|hungryroot|trifecta|factor meals|blue apron|home chef|freshly/i.test(n))return{cat:"Other / Uncategorized",conf:88,action:"discard",desc:""};
  // ══ WELLNESS / BODY R&D ══
  if(/art of smiles|maximus|stemcyte|gametime.*health|poshmark|nuuly/i.test(n))return{cat:"Health & Wellness R&D",conf:82,action:"approve",desc:`Health & wellness product research — ${cleanVendor(t.rawMerchant||"R&D")}.`};
  // ══ LEARNING / EDUCATION PLATFORMS ══
  if(/coursera|cengage|udemy|masterclass|skillshare|edx|pluralsight|codecademy|khan academy/i.test(n))return{cat:"Education & Training",conf:90,action:"approve",desc:`Professional education — ${cleanVendor(t.rawMerchant||"course")}. Training that supports business capability.`};
  // ══ NEWS / AUDIO SUBSCRIPTIONS ══
  if(/\bwsj\b|d j\*wsj|wall street journal|audible|youtubepremi|youtube premium|barrons|economist|financial times|bloomberg|business insider|oc register|nytimes|ny times/i.test(n))return{cat:"Subscriptions & Memberships",conf:85,action:"approve",desc:`Industry research subscription — ${cleanVendor(t.rawMerchant||"subscription")}. Business news and reference material.`};
  // ══ ENTERTAINMENT / EVENT TICKETS ══
  if(/tickpick|gametime|ticketmaster|stubhub|seatgeek|axs\.com|eventbrite|vivid seats/i.test(n))return{cat:"Business Meals & Entertainment",conf:80,action:"approve",desc:`Client entertainment — ${cleanVendor(t.rawMerchant||"event")}. Event tickets for business relationship development.`};
  // ══ TOURS / ACTIVITIES → Travel ══
  if(/viator|tripadvisor|getyourguide|klook|tours?\b/i.test(n))return{cat:"Travel & Lodging",conf:80,action:"approve",desc:`Business travel activity — ${cleanVendor(t.rawMerchant||"tour")}. Booked during client/project travel.`};
  // ══ STORAGE → Rent ══
  if(/extra space|public storage|storage unit|cubesmart|life storage|u-?haul storage/i.test(n))return{cat:"Rent & Lease",conf:88,action:"approve",desc:`Storage rental — ${cleanVendor(t.rawMerchant||"storage")}. Off-site storage for business materials and equipment.`};
  // ══ UPWORK → Contractors ══
  if(/upwork/i.test(n))return{cat:"Contractors & Freelancers",conf:92,action:"approve",desc:`Contractor payment via Upwork. Freelance services supporting business operations and project delivery.`};
  // ══ DONATIONS → discard ══
  if(/huntington\.org|donation|charity|\bgofundme\b|redcross|united way|borders fees/i.test(n))return{cat:"Other / Uncategorized",conf:85,action:"discard",desc:""};
  // ══ APPAREL / RETAIL / MARKETPLACES → Office Supplies ══
  if(/lululemon|j\.?crew|anthropologie|reformation|free ?people|suitsupply|abercrombie|revolve|onequince|quince|bloomingdale|sunglass hut|24s\.com|\brei\b|etsy|vuori|footloose|rimowa|monos|matches|poshmark|nuuly|birdy grey|kindred bravely|nike|banana ?republic|asos|llbean|athleta|patagonia|uniqlo|zara|h&m|gap\b|old navy|madewell|everlane|allbirds|luxome|jolieskinco|luggage/i.test(n))return{cat:"Office Supplies & Software",conf:80,action:"approve",desc:`Office supplies & materials — ${cleanVendor(t.rawMerchant||"supplies")}.`};
  // ══ FOREIGN / MISC RETAIL → Office Supplies ══
  if(/payu retai|freecharge|buddys warehousing|ppusind|lhm cto|24s /i.test(n))return{cat:"Office Supplies & Software",conf:70,action:"approve",desc:`Business supplies — ${cleanVendor(t.rawMerchant||"supplies")}.`};
  // ══ FAST FOOD → Business Meals ══
  if(/chick-?fil-?a|mcdonald|chipotle|subway|panera|shake shack|in-?n-?out|five guys|wendy|burger king|taco bell|popeyes|raising cane|sweetgreen|cava\b|panda express/i.test(n)){const seed2=`${t.date}${t.rawMerchant||""}${amt}`;return{cat:"Business Meals & Entertainment",conf:82,action:"approve",desc:`Working ${mt(t.date)} at ${cleanVendor(t.rawMerchant||"restaurant")}. Meal during business travel or a working session.`}}
  // ══ EREWHON / SPECIALTY GROCERY (direct) → Business Meals ══
  if(/erewhon/i.test(n)){const seed3=`${t.date}${t.rawMerchant||""}${amt}`;return{cat:"Business Meals & Entertainment",conf:82,action:"approve",desc:`Business ${mt(t.date)} provisions from ${cleanVendor(t.rawMerchant||"Erewhon")} with ${randContact(seed3)} ${randPurpose(seed3+"e")}.`}}
  // ══ TRAVEL & TRANSPORT (sub-typed) ══════════════
  // 1. CAR RENTAL → Car & Truck (Turo, Sixt, Enterprise, Hertz, etc.) — NOT airfare
  if(/\bturo\b|\bsixt\b|enterprise rent|\bhertz\b|\bavis\b|\bbudget rent|national car|alamo|dollar rent|thrifty|zipcar|getaround|car rental|rent.?a.?car|payless car/i.test(n)){const v=cleanVendor(t.rawMerchant||"car rental");return{cat:"Car & Truck Expenses",conf:88,action:"approve",desc:`Rental car — ${v}. Vehicle rented for business travel and client/project site visits.`}}
  // 2. AIRLINES → Travel (specific carriers + "airline"/"air lines" + "airways")
  if(/\bairlines?\b|air lines|\bairways\b|american air|delta air|southwest|jetblue|united air|alaska air|hawaiian ai|spirit air|frontier air|philippine airl|qatar air|turkish airl|virgin atlantic|saudia|lufthansa|aer lingus|breeze air|breeze aviation|etihad|tap airline|brussels airl|\bklm\b|\bqantas\b|air canada|emirates|electronic ticket|\bsouthwes|\bunited\b|swa\*|upgboard|ryanair|easyjet|allegiant|avianca|copa air|jetstar|westjet|air france|iberia|finnair|sas |eva air|ana |cathay|singapore air|china air|korean air|asiana|air india|indigo/i.test(n)){const v=cleanVendor(t.rawMerchant||"airline").replace(/\s*air(lines?|ways)?.*$/i," Airlines").trim();return{cat:"Travel & Lodging",conf:90,action:"approve",desc:`Business airfare — ${cleanVendor(t.rawMerchant||"airline")}. Flight for client and project travel.`}}
  // 3. HOTELS / LODGING → Travel
  if(/airbnb|marriott|hilton|hyatt|four seasons|courtyard|fairfield inn|springhill|hotel|htl|\binn\b|\bsuites\b|resort|motel|lodge|neemrana|grand solmar|solmar|booking\.com|agoda|doubletree|hostel|guest ?house|bed and breakfast|\bb&b\b|wyndham|best western|holiday inn|ramada|sheraton|westin|ritz|w hotel|kimpton|aloft|residence inn|homewood|hampton inn|embassy suites|la quinta|super 8|motel 6|travelodge|comfort inn|days inn/i.test(n)){const v=cleanVendor(t.rawMerchant||"lodging");return{cat:"Travel & Lodging",conf:88,action:"approve",desc:`Business lodging — ${v}. Overnight stay for in-person meetings and on-site project work.`}}
  // 4. TRAVEL AGENCIES / BOOKING → Travel
  if(/expedia|amextravel|amex travel|travelocity|priceline|kayak|orbitz|cl  travel|cl \*chase travel|chase travel|capital one travel|travel insured|travel insurance|trip insurance|hotels\.com|hotwire|vrbo|trip\.com/i.test(n)){const v=cleanVendor(t.rawMerchant||"travel");return{cat:"Travel & Lodging",conf:85,action:"approve",desc:`Business travel booking — ${v}. Arrangements for client and project travel.`}}
  // 5. SKI PASS / RECREATION VENUES → triage (could be personal)
  if(/ikon pass|epic pass|season pass|ski |resort pass/i.test(n)){const v=cleanVendor(t.rawMerchant||"pass");return{cat:"Travel & Lodging",conf:55,action:"triage",desc:`Recreation/travel — ${v}.`}}
  // 6. BOAT CHARTER / UNIQUE STAYS → Travel
  if(/makana charter|\bcharter\b|unique home stays|mammoth mountain chalet|\bchalet\b|\bvilla\b|mamahunes/i.test(n)){const v=cleanVendor(t.rawMerchant||"travel");return{cat:"Travel & Lodging",conf:80,action:"approve",desc:`Business travel & lodging — ${v}. Accommodation for client/project trip.`}}
  // 7. PARKING / TOLLS / TRANSIT → Car & Truck
  if(/parking|\btolls?\b|fastrak|ez.?pass|metro|transit|\bbart\b|caltrain|amtrak|\bmta\b|paygo|expresslane|yellow cab|\blyft\b|blacklane|\blimo\b|town car|car service|\btaxi\b|shuttle|via rideshare/i.test(n)){const v=cleanVendor(t.rawMerchant||"transit");return{cat:"Car & Truck Expenses",conf:82,action:"approve",desc:`Ground transportation — ${v}. Travel to business meetings and project sites.`}}
  // 8. AUTO REPAIR / BODY / TIRES → Car & Truck
  if(/tire|auto body|body shop|zoom auto|crown city|mechanic|smog|transmission|brakes|muffler|collision|autozone|o.?reilly|pep boys/i.test(n)){const v=cleanVendor(t.rawMerchant||"auto");return{cat:"Car & Truck Expenses",conf:85,action:"approve",desc:`Vehicle repair & maintenance — ${v}. Upkeep of vehicle used for business.`}}
  // 9. TOYOTA/AUTO FINANCING → triage (could be personal auto loan)
  if(/toyota ach|toyota financial|honda financial|ford credit|gm financial|auto loan|car payment|lexus financial/i.test(n)){const v=cleanVendor(t.rawMerchant||"auto");return{cat:"Car & Truck Expenses",conf:55,action:"triage",desc:`Vehicle financing — ${v}.`}}
  // SALON / BEAUTY / DEPT STORES → Office Supplies & materials
  if(/van michael|ara hair|pure nails|happy nails|earthling|day spa|salon|sephora|neiman|nordstrom|saks|bloomingdale|beauty|nail|hair studio|skin boutique|vinitas|threading|barber|blowdry|blow dry/i.test(n))return{cat:"Office Supplies & Software",conf:80,action:"approve",desc:`Office & materials — ${cleanVendor(t.rawMerchant||"supplies")}`};
  // NURSERIES / HARDWARE → Office Supplies (plants/materials)
  if(/nursery|home depot|ace hardware|lowes|pike nursery|blvd nursery|garden center|hardware|true value/i.test(n))return{cat:"Office Supplies & Software",conf:82,action:"approve",desc:`Office supplies & materials — ${cleanVendor(t.rawMerchant||"supplies")}`};
  // GROCERY (direct + DoorDash) → Supplies
  if(/^vons|^ralphs|^pavilions|^walmart|^safeway|^kroger|dd  vons|dd  pavilions|dd  ralphs|grocery|supermarket|whole foods|trader joe|sprouts farmers/i.test(n))return{cat:"Office Supplies & Software",conf:80,action:"approve",desc:`Business supplies — ${cleanVendor(t.rawMerchant||"supplies")}`};
  // UTILITIES (water/power/gas utilities)
  if(/water.*power|waterpower|water and power|dept of water|pasadena water|ladwp|so cal edison|socal edison|southern california edison|socalgas|so cal gas|pg&e|pge |edison|glendale water|burbank water|electric company|power company|municipal util/i.test(n))return{cat:"Utilities",conf:90,action:"approve",desc:`Utilities — ${cleanVendor(t.rawMerchant||"utility")}`};
  // COACHING → Educational
  if(/jacob zemer|coaching/i.test(n))return{cat:"Education & Training",conf:92,action:"approve",desc:`Business coaching — ${(t.rawMerchant||"coaching").split(" ").slice(0,3).join(" ")}`};
  // GYM / WHOOP → Health & Wellness R&D
  if(/whoop|speakeasy fitness|athena club|equinox|planet fitness|gym|athletic/i.test(n))return{cat:"Health & Wellness R&D",conf:88,action:"approve",desc:`Health & wellness R&D — ${(t.rawMerchant||"fitness").split(" ").slice(0,3).join(" ")}`};
  // PERSONAL GROCERY subscriptions → discard
  if(GROCERY_PERSONAL.test(n))return{cat:"Other / Uncategorized",conf:90,action:"discard",desc:""};
  // DoorDash/UberEats to a STORE → Supplies (not a meal)
  if(/target|vons|cvs|walgreens|pavilions|ralphs|safeway|costco|walmart|home ?depot|michaels|best buy|goopkitch|bristolfa|thehomede/i.test(n)&&/dd |doordash|uber eats/i.test(n)){const store=cleanVendor(t.rawMerchant||"");return{cat:"Office Supplies & Software",conf:82,action:"approve",desc:`Business supplies — ${store} (delivered)`}}
  // COFFEE → business meeting w/ rotating contact
  if(COFFEE_SHOPS.test(n)){const seed=`${t.date}${t.rawMerchant||""}${amt}`;const shop=(t.rawMerchant||"coffee shop").split(/\s{2,}/)[0].split("*").pop().trim();return{cat:"Business Meals & Entertainment",conf:85,action:"approve",desc:`Coffee meeting at ${shop} with ${randContact(seed)} ${randPurpose(seed+"c")}`}}
  // GAS → Car & Truck
  if(GAS_STATIONS.test(n)||/conoco|phillips 66|sinclair|speedway|circle k|quiktrip|racetrac|wawa|sheetz|marathon|bp |citgo|gulf oil|costco gas|sams club gas|kwik|casey/i.test(n)){const st=cleanVendor(t.rawMerchant||"fuel");return{cat:"Car & Truck Expenses",conf:87,action:"approve",desc:`Vehicle fuel — ${st}. Fuel for business travel and client/project site visits.`}}
  // CAR maintenance
  if(/jiffy lube|auto detail|oil change|firestone|midas|pep boys|discount tire|car wash|smog/i.test(n))return{cat:"Car & Truck Expenses",conf:88,action:"approve",desc:`Vehicle maintenance — ${(t.rawMerchant||"auto").split(/\s{2,}/)[0].trim()}`};
  // PHARMACY → Office Supplies (household/office items)
  if(PHARMACY.test(n)){const store=/cvs/i.test(n)?"CVS":/walgreens/i.test(n)?"Walgreens":"pharmacy";return{cat:"Office Supplies & Software",conf:80,action:"approve",desc:`Office & household supplies — ${store}`}}
  // AMAZON → Office Supplies (all)
  if(/amazon|amzn/i.test(n))return{cat:"Office Supplies & Software",conf:85,action:"approve",desc:`Office supplies — Amazon`};
  // INSURANCE
  if(/geico|lemonade insurance|state farm|allstate|progressive|zillion insurance/i.test(n))return{cat:"Insurance",conf:92,action:"approve",desc:`Business insurance — ${(t.rawMerchant||"insurance").split(/\s{2,}/)[0].trim()}`};
  // Known SaaS/subscriptions → Office Supplies & Software
  if(/adobe|typeform|canva|figma|notion|slack|zoom|dropbox|github|1password|openai|claude\.ai|anthropic|linkedin|fireflies|rize\.io|runway|wix|microsoft|google workspace|gsuite/i.test(n))return{cat:"Office Supplies & Software",conf:90,action:"approve",desc:`Software subscription — ${(t.rawMerchant||"software").split(/\s{2,}|\.|\*/)[0].trim()}`};
  // Internet/phone
  if(/spectrum|at&t|verizon|t-mobile|comcast|xfinity/i.test(n))return{cat:"Telephone & Internet",conf:90,action:"approve",desc:`Internet & phone — ${(t.rawMerchant||"telecom").split(/\s{2,}/)[0].trim()}`};
  // Media subscriptions → triage (mixed personal)
  if(/nytimes|spotify|hulu|netflix|youtube tv|disney|peacock|hbo|paramount|apple\.com-bill|amazon prime|the athletic/i.test(n))return{cat:"Subscriptions & Memberships",conf:55,action:"triage",desc:`Subscription — ${(t.rawMerchant||"subscription").split(/\s{2,}|\.|\*/)[0].trim()}`};
  // Shipping
  if(/fedex|ups |usps|dhl|shipstation|pirate ship/i.test(n))return{cat:"Shipping & Delivery",conf:90,action:"approve",desc:`Shipping — ${(t.rawMerchant||"shipping").split(/\s{2,}/)[0].trim()}`};
  // ── CATEGORY-LEVEL FALLBACKS (Copilot category) ──
  const seed=`${t.date}${t.rawMerchant||""}${amt}`;const vendor=(t.rawMerchant||"vendor").split(/\s{2,}|\*/).pop().trim()||(t.rawMerchant||"vendor");
  if(cat==="Restaurants"){return{cat:"Business Meals & Entertainment",conf:82,action:"approve",desc:`Business ${mt(t.date)} at ${vendor} with ${randContact(seed)}. Meal supported ${pick(MEETING_TYPES,seed+"m2")} covering ${randPurpose(seed+"r").replace(/^to /,"")}.`}}
  if(cat==="Travel & Vacation"){return{cat:"Travel & Lodging",conf:68,action:"triage",desc:`Business travel expense — ${vendor}. Travel or accommodation for client and project work.`}}
  if(cat==="Shops"||cat==="Clothing"){return{cat:"Office Supplies & Software",conf:78,action:"approve",desc:`Office supplies & materials — ${vendor}. Purchased for business operations.`}}
  if(cat==="Groceries"){return{cat:"Office Supplies & Software",conf:75,action:"approve",desc:`Business supplies — ${vendor}.`}}
  if(cat==="Car"){return{cat:"Car & Truck Expenses",conf:78,action:"approve",desc:`Vehicle expense — ${vendor}`}}
  if(cat==="Transportation"){return{cat:"Car & Truck Expenses",conf:75,action:"triage",desc:`Transportation — ${vendor}`}}
  if(cat==="Personal Care"){return{cat:"Other / Uncategorized",conf:50,action:"triage",desc:`${vendor}`}}
  if(cat==="Home"){return{cat:"Repairs & Maintenance",conf:60,action:"triage",desc:`Office/home — ${vendor}`}}
  if(cat==="Donations"){return{cat:"Other / Uncategorized",conf:60,action:"discard",desc:""}}
  if(cat==="Healthcare"){return{cat:"Other / Uncategorized",conf:80,action:"discard",desc:""}}
  if(cat==="Gym"){return{cat:"Health & Wellness R&D",conf:70,action:"triage",desc:`Health & wellness — ${vendor}`}}
  if(cat==="Subscriptions"){return{cat:"Subscriptions & Memberships",conf:60,action:"triage",desc:`Subscription — ${vendor}`}}
  // "Other" and anything else → triage with generic
  return{cat:"Other / Uncategorized",conf:45,action:"triage",desc:`${vendor} (${nd(t.date)})`};
}

function localCat(t){const rv=resolveVendor(t);
  if(rv&&rv.tier==="KB")return{category:rv.cat,confidence:rv.conf,action:rv.action,kind:rv.kind};
  const vr=vendorRule(t);if(vr&&vr.conf>=80){return{category:vr.cat,confidence:vr.conf,action:vr.action,vendorDesc:vr.desc,kind:vr.kind||"vendor"}}
  if(rv&&rv.tier==="morph")return{category:rv.cat,confidence:rv.conf,action:rv.action,kind:rv.kind};
  if(vr)return{category:vr.cat,confidence:vr.conf,action:vr.action,vendorDesc:vr.desc,kind:vr.kind||"vendor"};
  if(rv)return{category:rv.cat,confidence:rv.conf,action:rv.action,kind:rv.kind};const nm=(t.rawMerchant||t.rawDescription||t.description||"").toLowerCase();for(const[k,v]of Object.entries(CAT_RULES)){if(nm.includes(k))return{category:v,confidence:92}}const d=(t.rawDescription||t.description||t.rawMerchant||"").toLowerCase();if(t.source==="doordash"||t.source==="ubereats")return{category:"Business Meals & Entertainment",confidence:95};if(t.source==="uber")return{category:"Car & Truck Expenses",confidence:92};if(COFFEE.test(d)&&t.amount<15)return{category:"Business Meals & Entertainment",confidence:90};if(OFFICE.test(d))return{category:"Office Supplies & Software",confidence:t.amount<200?90:85};if(/at&t|verizon|t-mobile|comcast|spectrum|xfinity|internet|phone|cellular/i.test(d))return{category:"Telephone & Internet",confidence:90};if(/insurance|geico|state\s*farm|allstate/i.test(d))return{category:"Insurance",confidence:88};if(/hotel|marriott|hilton|hyatt|airbnb/i.test(d))return{category:"Travel & Lodging",confidence:90};if(/fedex|ups|usps|shipping|postage/i.test(d))return{category:"Shipping & Delivery",confidence:92};return null}

// ─── AI ───────────────────────────────────────────
async function aiCat(items,apiKey){const prompt=`Bookkeeping: categorize for TY${TY}. Categories: ${CATS.join(", ")}\nReturn ONLY JSON array: [{"index":0,"category":"...","confidence":85}]\n${items.map((t,i)=>`${i}. "${t.rawDescription||t.description}" $${t.amount.toFixed(2)}`).join("\n")}`;try{const r=await fetch("/api/categorize",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({anthropicKey:apiKey,prompt})});const d=await r.json();const txt=d.content?.map(b=>b.text||"").join("")||"";return JSON.parse(txt.replace(/```json|```/g,"").trim())}catch(e){return null}}
async function aiCatP(items,bs,apiKey,onP){const res=new Array(items.length).fill(null);let done=0;const batches=[];for(let i=0;i<items.length;i+=bs)batches.push({s:i,b:items.slice(i,i+bs)});let bi=0;async function w(){while(bi<batches.length){const{s,b}=batches[bi++];const cats=await aiCat(b,apiKey);if(cats)cats.forEach(c=>{if(c.index+s<items.length)res[c.index+s]=c});done+=b.length;onP(done)}}await Promise.all(Array.from({length:Math.min(2,batches.length)},()=>w()));return res}

// ─── Receipt Search ───────────────────────────────
function buildQ(t){const d=nd(t.date);const bef=dayAfter(d);const aft=dayBefore(d);if(t.source==="ubereats"||/uber eats|ubereats/i.test(t.rawMerchant||"")){const r=(t.restaurant||t.rawMerchant||"").split("(")[0].trim().split(" ").slice(0,2).join(" ");return`from:uber subject:order ${r} after:${aft} before:${bef}`}if(t.source==="uber"||/^uber(?! eats)/i.test(t.rawMerchant||""))return`from:uber subject:trip after:${aft} before:${bef}`;if(t.source==="doordash"||/doordash/i.test(t.rawMerchant||"")){const r=(t.restaurant||t.rawMerchant||"").replace(/dd \*doordash\s*/i,"").trim();if(!r||r.length<3)return null;return`from:doordash subject:receipt ${r.split(" ").slice(0,2).join(" ")} after:${aft} before:${bef}`}const merch=(t.rawMerchant||t.description||"").replace(/business (breakfast|lunch|dinner) at /i,"").split(" — ")[0].split(" to ")[0].split("(")[0].trim().split(" ").slice(0,2).join(" ");if(!merch||merch.length<3)return null;return`${merch} receipt after:${aft} before:${bef}`}
function buildQB(t){const d=nd(t.date);const bef=dayAfter(d);const aft=dayBefore(d);if(t.source==="ubereats"||/uber eats/i.test(t.rawMerchant||""))return`from:uber after:${aft} before:${bef}`;if(t.source==="uber"||/^uber/i.test(t.rawMerchant||""))return`from:uber trip after:${aft} before:${bef}`;if(t.source==="doordash"||/doordash/i.test(t.rawMerchant||""))return null;return`receipt after:${aft} before:${bef}`}
async function findReceipt(t,gTok,oTok){if(gTok){const q1=buildQ(t);if(q1){try{const r=await fetch("/api/gmail",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({token:gTok,query:q1})});const d=await r.json();if(d.found)return d}catch(e){}}const q2=buildQB(t);if(q2){try{const r=await fetch("/api/gmail",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({token:gTok,query:q2})});const d=await r.json();if(d.found)return d}catch(e){}}}if(oTok){const d2=nd(t.date);const q=(/uber/i.test(t.rawMerchant||""))?`from:uber AND (subject:receipt OR subject:trip) AND received>=${dayBefore(d2)}`:(t.source==="doordash"||/doordash/i.test(t.rawMerchant||""))?`from:doordash AND received>=${dayBefore(d2)}`:`subject:receipt AND received>=${dayBefore(d2)}`;try{const r=await fetch("/api/outlook",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({token:oTok,query:q})});const d3=await r.json();if(d3.found)return d3}catch(e){}}return{found:false}}

// ─── Dedup ────────────────────────────────────────
function crossDedup(a){const pl=a.filter(t=>t.source!=="creditcard"&&t.source!=="copilot"),cc=a.filter(t=>t.source==="creditcard"||t.source==="copilot"),m=new Set(),r=[...pl.map(t=>({...t,matchedCC:false}))];for(const c of cc){const cd=nd(c.date);let f=false;for(let i=0;i<pl.length;i++){if(m.has(i))continue;const amtDiff=Math.abs(c.amount-pl[i].amount);const amtPct=amtDiff/Math.max(c.amount,pl[i].amount,1);const dateOk=Math.abs((new Date(cd)-new Date(nd(pl[i].date)))/864e5)<=1;if(dateOk&&(amtDiff<0.02||amtPct<0.15)){m.add(i);r[i].matchedCC=true;r[i].ccDescription=c.description;if(c.amount>pl[i].amount){r[i].csvAmount=pl[i].amount;r[i].amount=c.amount}f=true;break}}if(!f)r.push({...c,matchedCC:false})}return r}
function intDedup(ts){const s=new Set();return ts.map(t=>{const k=`${nd(t.date)}|${t.amount.toFixed(2)}|${t.source}|${(t.rawDescription||t.description||"").slice(0,20).toLowerCase()}`;if(s.has(k))return{...t,isDuplicate:true};s.add(k);return{...t,isDuplicate:false}})}

// ─── UI Components ────────────────────────────────
function Bd({children,bg,color}){return <span style={{background:bg,color,padding:"2px 8px",borderRadius:5,fontSize:10,fontWeight:700,letterSpacing:.5,textTransform:"uppercase",whiteSpace:"nowrap"}}>{children}</span>}
function SB({source}){const m=SRC[source]||SRC.creditcard;const short={creditcard:"CC",doordash:"DD",ubereats:"UE",uber:"UR",copilot:"CP"};return <Bd bg={`${m.color}18`} color={m.color}>{m.icon}{short[source]||""}</Bd>}
function StB({status}){const m={pending:[T.amberBg,T.amber,"Pending"],approved:[T.greenBg,T.green,"OK"],duplicate:[T.redBg,T.red,"Dupe"],in_wave:[T.purpleBg,T.purple,"Wave"],pushed:[T.blueBg,T.blue,"Synced"]};const[bg,c,l]=m[status]||m.pending;return <Bd bg={bg} color={c}>{l}</Bd>}
function Cf({v}){const c=v>=80?T.green:v>=50?T.amber:T.red;return <span style={{fontSize:11,color:c,display:"inline-flex",alignItems:"center",gap:2}}><span style={{width:5,height:5,borderRadius:"50%",background:c}}/>{v}%</span>}
function SH({label,field,sort,setSort}){const a=sort.field===field;return <span onClick={()=>setSort({field,dir:a&&sort.dir==="asc"?"desc":"asc"})} style={{cursor:"pointer",userSelect:"none",display:"inline-flex",alignItems:"center",gap:2}}>{label}<span style={{fontSize:7,color:a?T.accent:T.dim}}>{a?(sort.dir==="asc"?"▲":"▼"):"⇅"}</span></span>}
function IC({icon,title,sub,color,desc,onFile,isActive}){const ref=useRef();return <div style={{background:T.card,border:`1px solid ${isActive?color:T.border}`,borderRadius:14,padding:20,position:"relative",overflow:"hidden"}}>{isActive&&<div style={{position:"absolute",top:0,left:0,right:0,height:2,background:color}}/>}<div style={{display:"flex",alignItems:"center",gap:9,marginBottom:8}}><span style={{fontSize:20}}>{icon}</span><div><div style={{fontWeight:700,fontSize:13}}>{title}</div><div style={{fontSize:10,color:T.dim}}>{sub}</div></div></div><p style={{fontSize:11,color:T.dim,lineHeight:1.6,marginBottom:12}}>{desc}</p><button onClick={()=>ref.current?.click()} style={{...bt(),width:"100%",background:`${color}15`,color,borderColor:`${color}30`}}>📁 Upload CSV</button><input ref={ref} type="file" accept=".csv" style={{display:"none"}} onChange={e=>onFile(e.target.files[0])}/></div>}
function MonthlyChart({txns,catFilter,srcFilter}){const data=useMemo(()=>{const m=Array(12).fill(0);txns.filter(t=>t.status!=="duplicate"&&t.status!=="in_wave"&&t.status!=="skipped").filter(t=>!catFilter||t.category===catFilter).filter(t=>!srcFilter||t.source===srcFilter).forEach(t=>{const mo=new Date(t.date).getMonth();if(mo>=0&&mo<12)m[mo]+=t.amount});return m},[txns,catFilter,srcFilter]);const max=Math.max(...data,1);const total=data.reduce((a,b)=>a+b,0);return <div><div style={{display:"flex",justifyContent:"space-between",marginBottom:12}}><span style={{fontSize:13,fontWeight:700}}>Monthly Expenses — TY{TY}</span><span style={{fontSize:13,fontWeight:700,color:T.accent}}>${total.toFixed(2)}</span></div><div style={{display:"flex",alignItems:"flex-end",gap:6,height:180,padding:"0 4px"}}>{data.map((v,i)=><div key={i} style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",gap:4}}><span style={{fontSize:9,color:T.dim}}>{v>0?`$${Math.round(v)}`:""}</span><div style={{width:"100%",background:v>0?`linear-gradient(180deg,${T.accent},${T.purple})`:`${T.dim}20`,borderRadius:4,height:`${Math.max((v/max)*140,2)}px`,transition:"height .3s",minHeight:2}}/><span style={{fontSize:10,color:T.dateText,fontWeight:600}}>{MONTHS[i]}</span></div>)}</div></div>}

// ═══════════════════════════════════════════════════
// MAIN APP
